// 幂等键：重复 POST 只执行一次副作用；同键不同载荷视为误用
const store = new Map();      // key -> { status, body, fingerprint }
const execCount = new Map();  // key -> 副作用执行次数
let sideEffects = 0;
let seq = 0;

function bump(key) {
  execCount.set(key, (execCount.get(key) || 0) + 1);
  sideEffects += 1;
}

function handlePost(headers, body) {
  const key = headers['idempotency-key'] || null;
  const fingerprint = JSON.stringify(body);

  if (key === null) {
    bump('<none>');
    return { status: 201, body: { id: String(++seq), title: body.title }, replayed: false,
             note: 'no key: executed' };
  }

  const cached = store.get(key);
  if (cached) {
    if (cached.fingerprint !== fingerprint) {
      return { status: 422, body: { code: 'idempotency-key-reuse',
               detail: 'the same key was reused with a different payload' },
               replayed: false, note: 'rejected' };
    }
    return { status: cached.status, body: cached.body, replayed: true, note: 'replayed from cache' };
  }

  bump(key);
  const created = { id: String(++seq), title: body.title };
  store.set(key, { status: 201, body: created, fingerprint });
  return { status: 201, body: created, replayed: false, note: 'executed and cached' };
}

const requests = [
  ['k-1', { title: 'alpha' }],
  ['k-1', { title: 'alpha' }],
  ['k-1', { title: 'alpha' }],
  ['k-2', { title: 'beta' }],
  ['k-2', { title: 'changed' }],
  [null,  { title: 'gamma' }],
  [null,  { title: 'gamma' }],
];

for (const pair of requests) {
  const key = pair[0];
  const body = pair[1];
  const headers = key ? { 'idempotency-key': key } : {};
  const r = handlePost(headers, body);
  console.log('key=' + (key || '<none>').padEnd(7) + 'title=' + body.title.padEnd(8)
    + 'status=' + String(r.status).padEnd(4) + 'id=' + String(r.body.id || '-').padEnd(3)
    + 'replayed=' + String(r.replayed).padEnd(6) + '(' + r.note + ')');
}

console.log('side_effects_total=' + sideEffects);
console.log('exec_per_key=' + JSON.stringify([...execCount.entries()].sort()));
console.log('k-1_executed_once=' + (execCount.get('k-1') === 1));
console.log('k-1_returns_same_id=' + (store.get('k-1').body.id === '1'));
console.log('k-1_reuse_with_new_payload_rejected=' + (execCount.get('k-2') === 1));
console.log('no_key_forwards_to_side_effect=' + (execCount.get('<none>') === 2));
